INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(84002, 'frFR', 'Ezh’ra, Voix du Tonnerre', 'Un bâton ancestral chargé de l’écho des tempêtes. À chaque incantation, le tonnerre répond.', 0),
(84003, 'frFR', 'Nairūn, Souffle des Anciens', 'Un souffle apaisant traverse ce bâton. À son passage, les blessures se referment, et les esprits murmurent la paix.', 0),
(84004, 'frFR', 'Kelrah, Harmonie des Éléments', 'Né de la confluence des quatre forces primordiales, ce bouclier équilibre feu, eau, air et terre pour apaiser, protéger et restaurer.', 0),
(84005, 'frFR', 'Drokhan, Poing des Tempêtes', 'Chaque coup porté avec Drokhan libère la fureur des éléments. Le feu gronde, la foudre danse, la terre cède.', 0),
(84006, 'frFR', 'Mak\'hor, Frappe des Esprits', 'Cette arme résonne à chaque impact du chant des ancêtres. Elle guide la main du chaman avec la force des éléments incarnés.', 0),
(84007, 'frFR', 'Kael’Thorr, Hurlement Sanglant', 'Créé pour abattre sans pitié, cet arc déchire l’air comme un cri de guerre. Chaque flèche cherche le cœur. Chaque tir réclame du sang.', 0),
(84008, 'frFR', 'Xer’thul, Maître des Chaînes', 'Les âmes liées à ce sceptre ne hurlent plus — elles obéissent. Chaque sort lancé est un ordre, chaque cible une offrande.', 0),
(84009, 'frFR', 'Varkhal, Lame du Silence Glacé', 'Forgée dans un tombeau de givre éternel, cette lame ne chante pas en frappant : elle fait taire. À son contact, le sang se fige avant de couler.', 0),
(84010, 'frFR', 'Skorrn, Morsure de l’Hiver Noir', 'Chaque entaille de Skorrn vole la chaleur du corps. La chair se craquèle, le givre s’infiltre, et la mort s’installe sans un bruit.', 0),
(84011, 'frFR', 'Vorthalak, Fléau des Vivants', 'Chaque coup porté infecte, chaque plaie ouverte pourrit. Vorthalak ne cherche pas à tuer rapidement, il appelle la chair à se trahir...', 0),
(84012, 'frFR', 'Drethmâr, Trône de Sang', 'On raconte qu’elle ne repose jamais à terre : là où elle chute, la terre saigne. Le porteur n’a pas besoin d’armure, il se dresse, nourri par chaque coup reçu. Ceux qui l’affrontent s’épuisent. Lui, non.', 0),
(84013, 'frFR', 'Elun\'dor, Voix des Cieux Silencieux', 'Les Anciens disent que ce bâton n’a pas été façonné mais semé. Lorsque le vent se tait et que les feuilles cessent de bouger, on peut entendre les étoiles parler à travers lui.', 0),
(84014, 'frFR', 'Liora, Berceuse des Racines', 'Là où elle touche, la sève circule à nouveau. Chaque blessure devient terre, chaque douleur une fleur.', 0),
(84015, 'frFR', 'Tharnok, Échine du Monde', 'Elle ne plie pas. Elle ne rompt pas. Elle encaisse, encore et encore, jusqu’à ce que l’ennemi oublie pourquoi il frappait.', 0),
(84016, 'frFR', 'Brakk, Fracture Totale', 'Ce n’est pas une arme. C’est un verdict. Elle ne tranche pas. Elle casse. Os, cuirasse ou muraille. Pas de distinction.', 0),
(84017, 'frFR', 'Drakthor, Le Brise-Écaille', 'Son éclat écarlate inspire la terreur aux plus anciens Wyrms et son tranchant peut fendre les écailles de Deathwing.', 0),
(84018, 'frFR', 'Malthen, Égide éternelle', 'Ses runes de protection ancestrales repoussent magie noire et fureur démoniaque, transformant son porteur en forteresse vivante que nul ne peut briser.', 0),
(84019, 'frFR', 'Vaelthis, Brise-sortilège', 'Son pouvoir consume les sorts les plus puissants et réduit en cendres quiconque ose défier son porteur.', 0),
(84020, 'frFR', 'Ashbringer, Fléau des morts', 'Son éclat divin a anéanti des armées entières de morts-vivants et son simple nom fait trembler les plus puissants. Aucune créature impie ne peut survivre à son contact.', 0),
(84021, 'frFR', 'Vindictus, Châtiment-ardent', 'Cette masse sacrée pulse d\'une fureur divine qui punit instantanément ceux qui osent menacer les justes. Son feu céleste brûle les âmes corrompues et sa justice implacable transforme la défense en vengeance purificatrice.', 0),
(84022, 'frFR', 'Salvation, Égide de Sanctuaire', 'Ce bouclier consacré émane une aura de protection céleste baignant les alliés dans une grâce divine.', 0),
(84023, 'frFR', 'Solareth, Souffle-de-vie', 'Forgée par les anges eux-mêmes, elle peut ramener les mourants du seuil de la mort et ses bénédictions divines guérissent même les malédictions les plus anciennes.', 0),
(84024, 'frFR', 'Kyresion, Rempart du Juste', 'En présence de Kyresion, les plaies se referment et les âmes sont apaisées.', 0),
(84025, 'frFR', 'Sha\'haggul, Voix des tourments', 'Il murmure constamment des secrets interdits qui brisent l\'esprit des ennemis. Ses tentacules d\'ombre s\'enroulent autour des âmes faibles, les plongeant dans une folie dévorante où seules résonnent les voix du Vide.', 0),
(84026, 'frFR', 'Luminaris, Bénédiction éternelle', 'Sa lumière dorée restaure instantanément la vie et l\'espoir, capable de guérir n\'importe quelle blessure et de purifier les âmes les plus souillées par ses bénédictions infinies.', 0),
(84027, 'frFR', 'Sanguineus, la silencieuse', 'Sa lame affûtée comme un rasoir trouve toujours les points vitaux, et son manche taillé dans l\'os permet des frappes furtives d\'une précision mortelle.', 0),
(84028, 'frFR', 'Carnifex, la pernicieuse', 'Cette dague maudite boit le sang de ses victimes et ne laisse jamais de traces. Chaque coup fatal nourrit sa soif insatiable, et sa lame empoisonnée transforme les assassinats en boucheries silencieuses où seuls les gémissements d\'agonie résonnent.', 0),
(84029, 'frFR', 'Shuor\'ror, Crépuscule du savoir', 'Tranche, coupe et massacre - il ne reste qu\'un sillon de sang et de boyaux. Cette lame n\'a jamais connu le repos contrairement à ses ennemis.', 0),
(84030, 'frFR', 'Shuadslayern, Aube de l\'oubli', 'Ses victimes ne portaient pas d\'armures et un coup suffisait à les réduire au silence.', 0),
(84031, 'frFR', 'Vorgath, plaie des dragons', '« J’ai vu cette épée planter un drake comme une tente dans la boue. Il a craché, hurlé, brûlé... mais il n’a pas bougé. Quand tu tiens Vorgath, c’est pas toi qui la manies. C’est elle qui décide quand le combat est fini. »', 0),
(84032, 'frFR', 'Draemorr, Brise-Monde', 'Chaque coup est un séisme. Les montagnes se fendent, la terre cède, les océans s\'écartent. Elle ne gagne pas les batailles. Elle les efface.', 0),
(84033, 'frFR', 'Aiguilles de l\'Aube', 'Nées du premier soleil, bénies par les anciens esprits. Chaque flèche perce l’ombre, chaque tir rappelle la lumière.', 0),
(84034, 'frFR', 'Crocs-de-Sang l\'Écorcheur', 'Il tranche, arrache, dépèce sans répit. Les cris de ses victimes se mêlent à ses dents jusqu\'à ce qu\'il ne reste que des morceaux.', 0),
(84102, 'frFR', 'Bouquin abîmé par le froid', 'Les pages sont rigides, craquantes comme de la glace.', 0),
(84103, 'frFR', 'Page gondolée par l’humidité', 'Fragile, prête à se réduire en poussière au moindre contact.', 0),
(84104, 'frFR', 'Cahier effrité aux bords', 'Il ondule comme une vague figée.', 0),
(84105, 'frFR', 'Manuscrit mangé par les mites', 'Percé de petits trous, semblable à un tissu rongé.', 0),
(84106, 'frFR', 'Volume couvert de poussière', 'À peine lisible sous une épaisse couche grise.', 0),
(84107, 'frFR', 'Livre à la reliure brisée', 'Son dos craque et laisse tomber des pages libres.', 0),
(84108, 'frFR', 'Bouquin troué par la moisissure', 'Parsemé de taches sombres et de trous circulaires.', 0),
(84109, 'frFR', 'Parchemin craquelé', 'Dur et fissuré, comme une vieille peau asséchée.', 0),
(84110, 'frFR', 'Registre taché d’encre', 'Des coulures noires brouillent les lignes d’écriture.', 0),
(84111, 'frFR', 'Carnet effacé par le soleil', 'L’encre pâle se dissipe, les mots deviennent fantômes.', 0),
(84112, 'frFR', 'Journal froissé et déchiré', 'Cabossé, aux pages froissées comme des cicatrices.', 0),
(84113, 'frFR', 'Livre rongé par l’humidité', 'Lourd, moisi, et collant entre les doigts.', 0),
(84114, 'frFR', 'Feuille brûlée aux coins', 'Les bords noircis se réduisent en cendres.', 0),
(84115, 'frFR', 'Livre écorné', 'Les angles pliés trahissent un usage négligé.', 0),
(84116, 'frFR', 'Volume oublié et moisi', 'Une odeur âcre émane de ses pages vertes de champignons.', 0),
(84117, 'frFR', 'Page chiffonnée au sol', 'Froissée, marquée de traces de pas.', 0),
(84118, 'frFR', 'Lettre tachée de sang', 'L’encre s’est diluée en auréoles troubles.', 0),
(84119, 'frFR', 'Enveloppe déchirée', 'Son contenu fragile est à moitié visible.', 0),
(84120, 'frFR', 'Missive maculée de boue', 'Les mots sont noyés sous des éclaboussures brunâtres.', 0),
(84121, 'frFR', 'Carton gondolé par la pluie', 'Lourd et mou, il ploie sous ses propres plis.', 0),
(84122, 'frFR', 'Page déchirée', 'Des lambeaux pendent encore, battant au vent.', 0),
(84123, 'frFR', 'Brouillon gribouillé et raturé', 'Les lignes se croisent, griffonnées avec rage.', 0),
(84124, 'frFR', 'Feuille effilochée', 'Ses fibres se détachent comme un tissu trop usé.', 0),
(84125, 'frFR', 'Signet effrité', 'Réduit à un mince fragment friable.', 0),
(84126, 'frFR', 'Volume aux pages volantes', 'Il craque dès qu’on tente de le plier.', 0),
(84127, 'frFR', 'Lettre pourrie', 'Les plis mous portent la trace d’un long abandon.', 0),
(84128, 'frFR', 'Courrier à moitié effacé', 'Porte les marques de liquides oubliés.', 0),
(84129, 'frFR', 'Parchemin détrempé', 'Les pages collées forment un bloc difforme.', 0),
(84130, 'frFR', 'Feuillet déchiré', 'Quasiment illisible.', 0),
(84131, 'frFR', 'Page brûlée', 'Le feu a léché les lettres et englouti les bords, il ne reste quasiment plus rien.', 0),
(84132, 'frFR', 'Rouleau abîmé', 'Il tombe en ruine lorsque vous le manipulez.', 0),
(84134, 'frFR', 'Parchemin effacé', 'Il ne reste que de vagues traces d\'écritures.', 0);
